 static List<string> log=new List<string>();static void Check(bool okay,string message){if(!okay)throw new Exception(message);log.Add("PASS "+message);}static T Field<T>(object owner,string name){return (T)owner.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(owner);}static Rect Bounds(FrameworkElement e,FrameworkElement root){return new Rect(e.TranslatePoint(new Point(0,0),root),new Size(e.ActualWidth,e.ActualHeight));}static async Task Ready(TerminalView view){for(int i=0;i<100;i++){if(view.DiagnosticReady)return;await Task.Delay(100);}throw new Exception("Terminal ready: "+view.State);}static async Task<Dictionary<string,object>> Options(TerminalView view){return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(await view.DiagnosticWeb.ExecuteScriptAsync("({font:term.options.fontFamily,size:term.options.fontSize,line:term.options.lineHeight,spacing:term.options.letterSpacing,cursor:term.options.cursorStyle,blink:term.options.cursorBlink,scrollback:term.options.scrollback,bg:term.options.theme.background})"));}
