 Theme.Apply("forest");var settings=new Settings();settings.Servers.Add(Storage.DefaultServer());editor=new SettingsWindow(settings.Copy(),true);Field<ComboBox>(editor,"terminalFont").SelectedItem="Consolas";Field<ComboBox>(editor,"terminalFont").Text="Consolas";Field<ComboBox>(editor,"terminalSize").SelectedItem="20";Field<ComboBox>(editor,"terminalLine").SelectedItem="1.50";Field<ComboBox>(editor,"terminalSpacing").SelectedItem="0.5";Field<ComboBox>(editor,"terminalCursor").SelectedIndex=1;Field<ComboBox>(editor,"terminalBuffer").SelectedItem="10000";Field<CheckBox>(editor,"terminalBlink").IsChecked=false;typeof(SettingsWindow).GetMethod("CaptureTerminalSettings",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(editor,null);var prefs=editor.Result.Terminal;Check(prefs.FontFamily=="Consolas"&&prefs.FontSize==20&&prefs.LineHeight==1.5&&prefs.LetterSpacing==.5&&prefs.CursorStyle=="block"&&!prefs.CursorBlink&&prefs.Scrollback==10000,"all seven terminal settings captured from real controls");string xml=Path.Combine(folder,"preferences.xml");using(var f=File.Create(xml))new XmlSerializer(typeof(Settings)).Serialize(f,editor.Result);Settings restored;using(var f=File.OpenRead(xml))restored=(Settings)new XmlSerializer(typeof(Settings)).Deserialize(f);Check(restored.Terminal.FontFamily=="Consolas"&&restored.Terminal.FontSize==20&&restored.Terminal.Scrollback==10000,"terminal settings XML roundtrip");var copy=restored.Copy();copy.Terminal.FontSize=12;Check(restored.Terminal.FontSize==20,"terminal preferences deep copy");using(var reader=new StringReader("<Settings><SelectedView>CPU</SelectedView></Settings>")){var legacy=(Settings)new XmlSerializer(typeof(Settings)).Deserialize(reader);Check(legacy.Terminal!=null&&legacy.Terminal.FontSize==16,"old settings gain compatible terminal defaults");}editor.RenderImage(Path.Combine(folder,"settings-top.png"),860,760,120);var scroll=Walk(editor.Root).OfType<ScrollViewer>().First(x=>x.Content is StackPanel);scroll.ScrollToVerticalOffset(560);editor.RenderImage(Path.Combine(folder,"settings-terminal.png"),860,760,120);UiReview.Record(editor.Root,Path.Combine(folder,"settings-terminal.csv"),"terminal preferences");editor.Close();editor=null;
 monitor=new MonitorWindow(true);monitor.Show();foreach(string theme in new[]{"graphite","light"}){monitor.ApplyAppearance(theme);foreach(int width in new[]{760,1200,1440}){monitor.Width=width;monitor.Height=760;await Task.Delay(80);var m=Program.Fixture("eight");m.Cpu="9.9%";m.Mem="1022976 / 33554432 MiB";foreach(var gpu in m.Gpus)gpu.Util="9.9";monitor.SetMetrics(m,false);await Task.Delay(960);monitor.UpdateLayout();var controls=new FrameworkElement[]{Field<MiniSpark>(monitor,"footerCpu"),Field<GpuMini>(monitor,"footerGpu"),Field<PixelMeter>(monitor,"footerMemory"),Field<TextBlock>(monitor,"memoryDetail")};var fixedRects=controls.Select(x=>Bounds(x,monitor.Root)).ToArray();m=Program.Fixture("eight");m.Cpu="100.0%";m.Mem="1024000 / 33554432 MiB";foreach(var gpu in m.Gpus)gpu.Util="100.0";monitor.SetMetrics(m,false);for(int frame=0;frame<12;frame++){await Task.Delay(65);monitor.UpdateLayout();for(int i=0;i<controls.Length;i++){if(controls[i].Visibility!=Visibility.Visible)continue;var rect=Bounds(controls[i],monitor.Root);Check(Math.Abs(rect.X-fixedRects[i].X)<.1&&Math.Abs(rect.Width-fixedRects[i].Width)<.1,"animated footer slot stable "+theme+" "+width+" frame "+frame+" slot "+i);}}var number=Field<TextBlock>(monitor,"MemoryValue");Check(!number.Text.Contains("/")&&number.Text.EndsWith(" GiB"),"memory number remains single value "+theme+" "+width);var cells=Field<Grid[]>(monitor,"footerCells");foreach(var cell in cells){var label=(TextBlock)cell.Children[0];var ft=new FormattedText(label.Text,System.Globalization.CultureInfo.CurrentUICulture,FlowDirection.LeftToRight,new Typeface(label.FontFamily,label.FontStyle,label.FontWeight,label.FontStretch),label.FontSize,Brushes.Black,1);Check(ft.Width<=label.ActualWidth+.2,"footer label fully visible "+label.Text+" "+width);}monitor.RenderImage(Path.Combine(folder,theme+"-footer-"+width+".png"),width,760,120);monitor.Root.ClearValue(FrameworkElement.WidthProperty);monitor.Root.ClearValue(FrameworkElement.HeightProperty);}}var mini=Field<GpuMini>(monitor,"footerGpu");foreach(int count in new[]{0,1,8,24,64}){mini.Set(Enumerable.Range(0,count).Select(i=>new Gpu{Index=i.ToString(),Util="80"}));await Task.Delay(520);monitor.UpdateLayout();var drawing=VisualTreeHelper.GetDrawing(mini);Check(drawing==null||drawing.Bounds.IsEmpty||drawing.Bounds.Right<=mini.ActualWidth+.1,"GPU mini bars stay inside fixed slot with "+count+" GPUs");}monitor.Exit();monitor=null;
 Theme.Apply("forest");workspace=new TerminalWorkspace(Storage.LocalServer(),prefs);terminal=new Window{Width=1100,Height=760,Content=workspace,Background=Theme.TerminalBackground,Resources=Theme.Resources()};workspace.Open(Storage.LocalServer());var view=workspace.ActiveView;Check(view.DiagnosticWeb.DefaultBackgroundColor.R==Theme.TerminalBackground.Color.R&&view.DiagnosticWeb.DefaultBackgroundColor.G==Theme.TerminalBackground.Color.G,"native terminal background set before initialization");terminal.Show();await Ready(view);await Task.Delay(160);var actual=await Options(view);Check(Convert.ToInt32(actual["size"])==20&&Convert.ToString(actual["font"]).StartsWith("Consolas")&&Convert.ToDouble(actual["line"])==1.5&&Convert.ToDouble(actual["spacing"])==.5&&Convert.ToString(actual["cursor"])=="block"&&!Convert.ToBoolean(actual["blink"])&&Convert.ToInt32(actual["scrollback"])==10000,"all terminal preferences reached real xterm");var updated=prefs.Copy();updated.FontSize=14;updated.LineHeight=1.1;updated.CursorStyle="underline";workspace.ApplyOptions(updated);await Task.Delay(180);actual=await Options(view);Check(Convert.ToInt32(actual["size"])==14&&Convert.ToString(actual["cursor"])=="underline"&&view.DiagnosticSessionsStarted==1,"live preferences preserve existing shell session");foreach(string theme in Theme.Keys){Theme.Apply(theme);workspace.RefreshTheme();await Task.Delay(100);actual=await Options(view);string expected="#"+Theme.TerminalBackground.Color.R.ToString("X2")+Theme.TerminalBackground.Color.G.ToString("X2")+Theme.TerminalBackground.Color.B.ToString("X2");Check(string.Equals(Convert.ToString(actual["bg"]),expected,StringComparison.OrdinalIgnoreCase),"real terminal follows theme "+theme);Check(view.DiagnosticWeb.DefaultBackgroundColor.R==Theme.TerminalBackground.Color.R&&view.DiagnosticWeb.DefaultBackgroundColor.G==Theme.TerminalBackground.Color.G,"native background follows theme "+theme);}using(var capture=File.Create(Path.Combine(folder,"terminal-live.png")))await view.DiagnosticWeb.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,capture);var tabs=Field<StackPanel>(workspace,"tabs");var row=tabs.Children.OfType<Grid>().Single();typeof(TerminalWorkspace).GetMethod("Close",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(workspace,new object[]{view,row});var empty=Field<Border>(workspace,"emptyState");Check(workspace.ActiveView==null&&empty.Visibility==Visibility.Visible&&empty.Background==Theme.TerminalBackground,"closing last tab shows themed empty state");Snapshot.Save(workspace,Path.Combine(folder,"terminal-empty.png"),1100,760,120,null);workspace.ClearValue(FrameworkElement.WidthProperty);workspace.ClearValue(FrameworkElement.HeightProperty);workspace.Open(Storage.LocalServer());var second=workspace.ActiveView;await Ready(second);await Task.Delay(120);actual=await Options(second);Check(Convert.ToInt32(actual["size"])==14&&empty.Visibility==Visibility.Collapsed,"new terminal inherits settings and hides empty state");workspace.Dispose();workspace=null;terminal.Close();terminal=null;File.WriteAllLines(Path.Combine(folder,"v122-results.txt"),log);app.Shutdown(0);
 }catch(Exception ex){File.WriteAllLines(Path.Combine(folder,"v122-results.txt"),log);File.WriteAllText(Path.Combine(folder,"v122-error.txt"),ex.ToString());if(editor!=null)editor.Close();if(monitor!=null)monitor.Exit();if(workspace!=null)workspace.Dispose();if(terminal!=null)terminal.Close();app.Shutdown(1);}}
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(root,i)))yield return child;}
